// ── SHARED STORAGE FOR GRANTS — Monday.com ────────────────────────
// localStorage alone never leaves the device that set it, so a grant an
// MD makes on their own laptop was invisible to the agent it was meant
// for, opening the app on their own phone or computer. One item per
// grant on a shared board, named "<agentId>__<page>", is the source of
// truth; the localStorage map above is just a same-device cache of it.
const TOOL_GRANTS_BOARD_KEY = 'dba_tool_grants_board_id';
// Org-wide default so every device works out of the box — no per-device
// setup step required. A local override (if ever set) still wins.
const TOOL_GRANTS_BOARD_DEFAULT = '18432605333'; // "DBA Tool Access Grants"
function getToolGrantsBoardId() {
  return localStorage.getItem(TOOL_GRANTS_BOARD_KEY) || TOOL_GRANTS_BOARD_DEFAULT;
}
let _toolGrantsRefreshed = false;

async function refreshToolGrantsFromMonday() {
  const boardId = getToolGrantsBoardId();
  if (!boardId || typeof AUTH === 'undefined' || !AUTH.getMondayKey?.()) return false;
  try {
    const res = await mondayQuery(`{ boards(ids:${boardId}) { items_page(limit:500) { items { id name } } } }`);
    const items = res?.data?.boards?.[0]?.items_page?.items || [];
    const rebuilt = {};
    items.forEach(it => {
      if (it.name.includes('__setting:')) return;   // hub settings share this board; they are not tool grants
      const sep = it.name.indexOf('__');
      if (sep < 0) return;
      const agentId = it.name.slice(0, sep);
      const page = it.name.slice(sep + 2);
      if (!rebuilt[agentId]) rebuilt[agentId] = [];
      if (!rebuilt[agentId].includes(page)) rebuilt[agentId].push(page);
    });
    localStorage.setItem(TOOL_GRANTS_KEY, JSON.stringify(rebuilt));
    return true;
  } catch(e) {
    console.warn('Tool grants: could not sync from Monday:', e.message);
    return false;
  }
}

async function syncGrantToMonday(agentId, page, granted) {
  const boardId = getToolGrantsBoardId();
  if (!boardId || typeof AUTH === 'undefined' || !AUTH.getMondayKey?.()) return;
  const itemName = `${agentId}__${page}`;
  try {
    const res = await mondayQuery(`{ boards(ids:${boardId}) { items_page(limit:500) { items { id name } } } }`);
    const items = res?.data?.boards?.[0]?.items_page?.items || [];
    const existing = items.find(it => it.name === itemName);
    if (granted && !existing) {
      await mondayQuery(`mutation { create_item(board_id:${boardId}, item_name:"${itemName}") { id } }`);
    } else if (!granted && existing) {
      await mondayQuery(`mutation { delete_item(item_id:${existing.id}) { id } }`);
    }
  } catch(e) {
    console.warn('Tool grants: could not sync to Monday:', e.message);
  }
}

function setToolGrant(agentId, page, granted) {
  const all = getAllToolGrants();
  const current = new Set(all[agentId] || []);
  if (granted) current.add(page); else current.delete(page);
  if (current.size) all[agentId] = [...current]; else delete all[agentId];
  try { localStorage.setItem(TOOL_GRANTS_KEY, JSON.stringify(all)); } catch(e) {}
  syncGrantToMonday(agentId, page, granted); // fire-and-forget — this device's cache is already updated above
}

// ── HUB SETTINGS (central, admin-controlled) ─────────────────────────
// Live on the same Monday board as tool grants, one item per setting, named
// "<scope>__setting:<key>=<on|off>". Scope is "all" (everyone) or one agent's
// login id. Precedence: that agent's own setting, then the "all" setting, then
// the default below. Same-device cache so the hub renders instantly; Monday is
// the source of truth and the cache is refreshed on every hub load.
const HUB_SETTINGS_KEY = 'dba_hub_settings';           // { all:{key:'on'|'off'}, agents:{ id:{key:'on'|'off'} } }
const HUB_SETTING_DEFAULTS = { collapsible: 'on' };    // sections can be collapsed unless an admin turns it off
function getHubSettings() {
  try { return JSON.parse(localStorage.getItem(HUB_SETTINGS_KEY) || '{}') || {}; } catch (e) { return {}; }
}
function hubSettingFor(agentId, key) {
  const s = getHubSettings();
  const own = s.agents && s.agents[agentId] && s.agents[agentId][key];
  if (own === 'on' || own === 'off') return own;
  const all = s.all && s.all[key];
  if (all === 'on' || all === 'off') return all;
  return HUB_SETTING_DEFAULTS[key];
}
const hubCollapsibleFor = agentId => hubSettingFor(agentId, 'collapsible') === 'on';

const HUB_SETTING_RULE = 'query_params:{rules:[{column_id:"name",compare_value:["__setting:"],operator:contains_text}]}';
// Returns true only when the settings changed (so the hub knows to redraw).
async function refreshHubSettingsFromMonday() {
  const boardId = getToolGrantsBoardId();
  if (!boardId || typeof AUTH === 'undefined' || !AUTH.getMondayKey?.()) return false;
  try {
    let items = [], cursor = null, pages = 0;
    do {
      const res = await mondayQuery(cursor
        ? `{ next_items_page(limit:200, cursor:"${cursor}") { cursor items { id name } } }`
        : `{ boards(ids:${boardId}) { items_page(limit:200, ${HUB_SETTING_RULE}) { cursor items { id name } } } }`);
      if (res?.errors?.length) throw new Error(res.errors[0].message);
      const page = cursor ? res?.data?.next_items_page : res?.data?.boards?.[0]?.items_page;
      if (!page) throw new Error('no data returned');
      items = items.concat(page.items || []); cursor = page.cursor || null;
    } while (cursor && ++pages < 10);
    const next = { all: {}, agents: {} };
    items.forEach(it => {
      const m = /^(.+?)__setting:([a-z-]+)=(on|off)$/.exec(it.name);
      if (!m) return;
      if (m[1] === 'all') next.all[m[2]] = m[3];
      else (next.agents[m[1]] = next.agents[m[1]] || {})[m[2]] = m[3];
    });
    const changed = JSON.stringify(next) !== JSON.stringify({ all: getHubSettings().all || {}, agents: getHubSettings().agents || {} });
    localStorage.setItem(HUB_SETTINGS_KEY, JSON.stringify(next));
    return changed;
  } catch (e) {
    console.warn('Hub settings: could not sync from Monday:', e.message);
    return false;       // keep whatever this device already has
  }
}

// value: 'on' | 'off' | 'inherit' (inherit removes the setting for that scope).
// Throws if Monday can't be reached, so an admin never thinks a change saved when it didn't.
async function setHubSetting(scope, key, value) {
  if (!/^[A-Za-z0-9_-]+$/.test(scope) || !/^[a-z-]+$/.test(key)) throw new Error('Invalid setting');
  const boardId = getToolGrantsBoardId();
  if (!boardId || typeof AUTH === 'undefined' || !AUTH.getMondayKey?.()) throw new Error('Monday.com is not connected on this device.');
  const prefix = `${scope}__setting:${key}=`;
  const want = (value === 'on' || value === 'off') ? prefix + value : null;
  const res = await mondayQuery(`{ boards(ids:${boardId}) { items_page(limit:200, query_params:{rules:[{column_id:"name",compare_value:["${prefix}"],operator:contains_text}]}) { items { id name } } } }`);
  if (res?.errors?.length) throw new Error(res.errors[0].message);
  const existing = (res?.data?.boards?.[0]?.items_page?.items || []).filter(it => it.name.startsWith(prefix));
  const keep = want ? existing.find(it => it.name === want) : null;
  if (want && !keep) {                               // add the new value first, so a failure can't leave the setting blank
    const c = await mondayQuery(`mutation { create_item(board_id:${boardId}, item_name:"${want}") { id } }`);
    if (c?.errors?.length || !c?.data?.create_item?.id) throw new Error(c?.errors?.[0]?.message || 'Monday did not save the setting');
  }
  for (const it of existing) {
    if (it === keep) continue;
    const d = await mondayQuery(`mutation { delete_item(item_id:${it.id}) { id } }`);
    if (d?.errors?.length) throw new Error(d.errors[0].message);
  }
  const cur = getHubSettings(); cur.all = cur.all || {}; cur.agents = cur.agents || {};
  const holder = scope === 'all' ? cur.all : (cur.agents[scope] = cur.agents[scope] || {});
  if (want) holder[key] = value; else delete holder[key];
  if (scope !== 'all' && !Object.keys(holder).length) delete cur.agents[scope];
  try { localStorage.setItem(HUB_SETTINGS_KEY, JSON.stringify(cur)); } catch (e) {}
  return true;
}

